// LinkedIn — binary search on sorted arrays: k closest elements (LeetCode 658), then distinct values in a huge
// sorted array without scanning every element.
public static class SortedSearch {
    // The k elements closest to x, ascending; ties go to the smaller element. O(log(n - k) + k).
    public static List<int> KClosest(int[] arr, int k, int x) {
        if (arr == null || k <= 0) return new List<int>();
        if (k > arr.Length) throw new ArgumentOutOfRangeException(nameof(k));
        int lo = 0, hi = arr.Length - k;                     // the answer is a window arr[lo .. lo+k-1]
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            // compare the element just left of the window with the one just past it
            if ((long)x - arr[mid] > (long)arr[mid + k] - x) lo = mid + 1; else hi = mid;
        }
        return arr.Skip(lo).Take(k).ToList();
    }

    // Distinct values in a sorted array: jump over each run with a binary search for its end.
    // O(d log n) for d distinct values — far better than O(n) when n is huge and d is small.
    public static int CountDistinct(int[] a) {
        if (a == null || a.Length == 0) return 0;
        int count = 0, i = 0;
        while (i < a.Length) {
            count++;
            int lo = i, hi = a.Length - 1, v = a[i];
            while (lo < hi) { int mid = lo + (hi - lo + 1) / 2; if (a[mid] == v) lo = mid; else hi = mid - 1; }
            i = lo + 1;                                       // first index past the run of v
        }
        return count;
    }
}
